const envelope = $json;
if (!envelope || envelope.type !== 'fan.nearby_concert_available' || envelope.version !== 1) {
  throw new Error('Unsupported CrowdRelay event');
}
const data = envelope.data ?? {};
for (const key of ['email', 'event_slug', 'event_title', 'starts_at']) {
  if (data[key] === undefined || data[key] === null || data[key] === '') {
    throw new Error(`Missing nearby concert field: ${key}`);
  }
}
const base = ("https://virya.music" || 'https://virya.music').replace(/\/$/, '');
const eventUrl = `${base}/pl/live/${encodeURIComponent(data.event_slug)}/`;
return [{ json: {
  event_id: envelope.id,
  mail: {
    template: 'crowdrelay-new-gig',
    to: data.email,
    variables: {
      display_name: data.display_name ?? null,
      locale: data.locale ?? 'pl-PL',
      event_title: data.event_title,
      event_description: data.distance_km == null ? null : `Koncert około ${data.distance_km} km od Twojego miasta.`,
      starts_at: data.starts_at,
      venue: data.venue ?? null,
      venue_address: null,
      city: data.city_name ?? null,
      event_url: eventUrl,
      ticket_url: `${eventUrl}#tickets`,
      rsvp_url: null,
      follow_url: "https://www.bandsintown.com/a/15587796-virya" || 'https://www.bandsintown.com/a/15587796-virya?trigger=track'
    },
    idempotency_key: envelope.id
  }
} }];

